  [Test]
  public void f2test3() {
        driver.Navigate().GoToUrl("https://ogimilwebshop.com");
        driver.Manage().Window.Size = new System.Drawing.Size(1054, 808);

        WebDriverWait wait = new WebDriverWait(driver, TimeSpan.FromSeconds(10));
        IJavaScriptExecutor js = (IJavaScriptExecutor)driver;

        // Klik na dugme za prijavu
        wait.Until(ExpectedConditions.ElementToBeClickable(By.CssSelector(".porto-sicon-header > p"))).Click();

        // Klik na polje za unos korisničkog imena
        wait.Until(ExpectedConditions.ElementToBeClickable(By.Id("user_login"))).Click();

        // Osiguraj da je login forma vidljiva
        wait.Until(ExpectedConditions.ElementIsVisible(By.CssSelector(".login"))).Click();

        // Unesi korisničko ime
        wait.Until(ExpectedConditions.ElementIsVisible(By.Id("user_login"))).SendKeys("dzanakrnjic572003");

        // Unesi lozinku
        wait.Until(ExpectedConditions.ElementIsVisible(By.Id("user_pass"))).SendKeys("Password123");

        // Klik na dugme za prijavu
        wait.Until(ExpectedConditions.ElementToBeClickable(By.Id("wp-submit"))).Click();

        // Klik na polje za pretragu
        wait.Until(ExpectedConditions.ElementToBeClickable(By.Name("s"))).Click();


        // Unesi tekst za pretragu
        wait.Until(ExpectedConditions.ElementIsVisible(By.Name("s"))).SendKeys("labrosan balzam za usne defence");

        // Klik na dugme za pretragu
        wait.Until(ExpectedConditions.ElementToBeClickable(By.CssSelector(".loading"))).Click();

        var starElement = wait.Until(ExpectedConditions.ElementIsVisible(By.LinkText("3")));

        // Skroluj do elementa
        IJavaScriptExecutor java = (IJavaScriptExecutor)driver;
        java.ExecuteScript("arguments[1].scrollIntoView(true);", starElement);
        Thread.Sleep(10000);
        // Klikni na element
        wait.Until(ExpectedConditions.ElementToBeClickable(starElement)).Click();


        // Klik na dugme za slanje komentara (submit)
        wait.Until(ExpectedConditions.ElementToBeClickable(By.Id("submit"))).Click();

        // Provera greške na stranici
        wait.Until(ExpectedConditions.ElementIsVisible(By.Id("error-page")));
        string errorMessage = wait.Until(ExpectedConditions.ElementIsVisible(By.CssSelector("p:nth-child(1)"))).Text;

        // Asertuj da je greška prikazana
        Assert.That(errorMessage, Is.EqualTo("Greška: molimo vas da upišete komentar."));

        // Zatvori preglednik
        driver.Close();
    }
