  [Test]
  public void f3test2() {
    driver.Navigate().GoToUrl("https://ogimilwebshop.com");
    driver.Manage().Window.Size = new System.Drawing.Size(1552, 840);
        driver.FindElement(By.CssSelector(".porto-sicon-box-link p")).Click();
        driver.FindElement(By.Id("user_login")).Click();
    driver.FindElement(By.Id("user_login")).SendKeys("dzanakrnjic572003");
    driver.FindElement(By.Id("user_pass")).Click();
    driver.FindElement(By.Id("user_pass")).SendKeys("Password123");
    driver.FindElement(By.Id("wp-submit")).Click();
    {
      var element = driver.FindElement(By.LinkText("Moj nalog"));
      Actions builder = new Actions(driver);
      builder.MoveToElement(element).ClickAndHold().Perform();
    }
    {
      var element = driver.FindElement(By.LinkText("Moj nalog"));
      Actions builder = new Actions(driver);
      builder.MoveToElement(element).Perform();
    }
    {
      var element = driver.FindElement(By.LinkText("Moj nalog"));
      Actions builder = new Actions(driver);
      builder.MoveToElement(element).Release().Perform();
    }
    driver.FindElement(By.LinkText("Moj nalog")).Click();
    driver.FindElement(By.CssSelector(".Simple-Line-Icons-social-dropbox")).Click();
    driver.FindElement(By.CssSelector(".account-sub-title")).Click();
    Assert.That(driver.FindElement(By.CssSelector(".account-sub-title")).Text, Is.EqualTo("Narudžbe"));
  }
